import os,json,subprocess
from pathlib import Path
src=Path("/var/www/lowcost-europa");root=Path("/srv/projects/lowcost-europa")
dst=root/"www"
out={"phase":"lowcost-www-preflight"}
for n,p in (("src",src),("project",root),("dst",dst)):
 try:
  s=p.stat();out[n]={"is_directory":p.is_dir() and not p.is_symlink(),"mode":oct(s.st_mode & 0o777),"uid":s.st_uid,"gid":s.st_gid,"dev":s.st_dev,"inode":s.st_ino,"entries":len(list(p.iterdir())) if p.is_dir() else 0}
 except FileNotFoundError:out[n]={"exists":False}
def check(*cmd):
 try:
  r=subprocess.run(cmd,capture_output=True,text=True,timeout=6);return r.returncode==0
 except Exception:return False
out["nginx_ok"]=check("nginx","-t")
out["www_data_can_traverse_root"]=check("runuser","-u","www-data","--","test","-x",str(root))
out["www_data_can_read_source"]=check("runuser","-u","www-data","--","test","-r",str(src))
out["nginx_disable_symlinks_found"]=False
refs=[]
for p in [Path("/etc/nginx/nginx.conf"),*Path("/etc/nginx/sites-available").glob("*")]:
 try:
  t=p.read_text()
  if "disable_symlinks on" in t:out["nginx_disable_symlinks_found"]=True
  if "/var/www/lowcost-europa" in t:refs.append(p.name)
 except Exception:continue
out["nginx_reference_file_names"]=refs
print(json.dumps(out,sort_keys=True))
